import{c as n}from"./nav-DbDnNZkH.js";/* empty css              */const a=document.getElementById("accountError"),o=document.getElementById("logoutButton"),r=document.getElementById("profileUsername"),c=document.getElementById("profileEmail");async function i(){try{const e=await fetch("/api/auth/me"),t=await e.json();if(!e.ok||!t.success)throw new Error(t.error||"Gagal memuat profil akun.");r.textContent=t.profile.username||"-",c.textContent=t.profile.email||t.user.email||"-"}catch(e){a.textContent=e.message}}o.addEventListener("click",async()=>{o.disabled=!0,o.textContent="Keluar...";try{await fetch("/api/auth/logout",{method:"POST"})}finally{window.location.assign("/login")}});i();n();
